'use strict';
// Catalog invariants: stable ids, real per-skin images, case odds / house edge, theme art.
// The catalog itself is generated by scripts/build-catalog.js (run `node scripts/build-catalog.js --report`
// for the full expected-value table).
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const data = require('../public/js/data.js');

const RARITIES = ['consumer', 'industrial', 'milspec', 'restricted', 'classified', 'covert', 'gold'];
const allSkins = RARITIES.flatMap(r => data.skins[r].map(s => Object.assign({ rarity: r }, s)));

// Ids 1-34 are referenced by players' inventories: name and rarity must never change.
const ORIGINAL = {
    1: ['P250 | Sand Dune', 'consumer'], 2: ['MAC-10 | Silver', 'consumer'], 3: ['Negev | Army Sheen', 'consumer'],
    4: ['PP-Bizon | Sand Dashed', 'consumer'], 5: ['UMP-45 | Urban DDPAT', 'industrial'], 6: ['G3SG1 | Safari Mesh', 'industrial'],
    7: ['Five-SeveN | Forest Night', 'industrial'], 8: ['Dual Berettas | Contractor', 'industrial'],
    9: ['M4A1-S | Boreal Forest', 'milspec'], 10: ['AK-47 | Safari Mesh', 'milspec'], 11: ['Glock-18 | Night', 'milspec'],
    12: ['USP-S | Forest Leaves', 'milspec'], 13: ['FAMAS | Colony', 'milspec'], 14: ['AWP | Pit Viper', 'restricted'],
    15: ['M4A4 | Magnesium', 'restricted'], 16: ['Desert Eagle | Cobalt', 'restricted'], 17: ['P90 | Trigon', 'restricted'],
    18: ['AK-47 | Blue Laminate', 'restricted'], 19: ['AWP | Redline', 'classified'], 20: ['M4A1-S | Atomic Alloy', 'classified'],
    21: ['AK-47 | Redline', 'classified'], 22: ['USP-S | Kill Confirmed', 'classified'], 23: ['Glock-18 | Water Elemental', 'classified'],
    24: ['AWP | Asiimov', 'covert'], 25: ['AK-47 | Vulcan', 'covert'], 26: ['M4A4 | Howl', 'covert'], 27: ['AWP | Dragon Lore', 'covert'],
    28: ['M4A1-S | Knight', 'covert'], 29: ['★ Karambit | Doppler', 'gold'], 30: ['★ Butterfly Knife | Fade', 'gold'],
    31: ['★ M9 Bayonet | Crimson Web', 'gold'], 32: ['★ Sport Gloves | Pandora', 'gold'], 33: ['★ Skeleton Knife | Fade', 'gold'],
    34: ['★ Bayonet | Tiger Tooth', 'gold']
};
const ORIGINAL_CASES = {
    1: ['Caja Principiante', 0.5, 'recruit'], 2: ['Caja de Armas', 2.5, 'arsenal'], 3: ['Caja AK-47', 5, 'kalashnikov'],
    4: ['Caja AWP', 8, 'sniper'], 5: ['Caja Premium', 15, 'premium'], 6: ['Caja de Cuchillos', 25, 'blade'],
    7: ['Caja Legendaria', 50, 'legend'], 8: ['Caja Dragon', 100, 'dragon']
};

function evOf(c) {
    const chances = data.getItemChances(c.items);
    return c.items.reduce((sum, it, i) => sum + chances[i] / 100 * it.price, 0);
}

test('catalog size: 120-210 skins across every rarity, 16+ cases', () => {
    assert.ok(allSkins.length >= 120 && allSkins.length <= 210, 'skins: ' + allSkins.length);
    RARITIES.forEach(r => assert.ok(data.skins[r].length >= 4, r + ' has ' + data.skins[r].length));
    assert.ok(data.cases.length >= 16, 'cases: ' + data.cases.length);
});

test('original skin ids 1-34 keep their name and rarity', () => {
    Object.keys(ORIGINAL).forEach(id => {
        const s = allSkins.find(x => x.id === Number(id));
        assert.ok(s, 'id ' + id + ' exists');
        assert.equal(s.name, ORIGINAL[id][0], 'name of ' + id);
        assert.equal(s.rarity, ORIGINAL[id][1], 'rarity of ' + id);
    });
});

test('skin ids and names are unique, prices positive, tiers broadly ordered by price', () => {
    assert.equal(new Set(allSkins.map(s => s.id)).size, allSkins.length);
    assert.equal(new Set(allSkins.map(s => s.name)).size, allSkins.length);
    allSkins.forEach(s => {
        assert.ok(Number.isInteger(s.id) && s.id > 0);
        assert.ok(s.price > 0 && Number.isFinite(s.price), s.name);
        assert.equal(Math.round(s.price * 100) / 100, s.price, s.name + ' has sub-cent price');
    });
    const mean = r => data.skins[r].reduce((a, s) => a + s.price, 0) / data.skins[r].length;
    for (let i = 1; i < RARITIES.length; i++) {
        assert.ok(mean(RARITIES[i]) > mean(RARITIES[i - 1]), RARITIES[i] + ' should be pricier than ' + RARITIES[i - 1]);
    }
    assert.equal(allSkins.find(s => s.id === 27).price, 3500);
    assert.equal(allSkins.find(s => s.id === 21).price, 18);
});

test('every skin has its own Steam CDN image (no two skins share one, none is the placeholder)', () => {
    const seen = new Map();
    allSkins.forEach(s => {
        assert.match(s.image, /^https:\/\/community\.(akamai|cloudflare)\.steamstatic\.com\/economy\/image\/[A-Za-z0-9_-]{40,}$/, s.name);
        assert.ok(!seen.has(s.image), s.name + ' shares an image with ' + seen.get(s.image));
        seen.set(s.image, s.name);
    });
    assert.notEqual(allSkins.find(s => s.id === 21).image, allSkins.find(s => s.id === 25).image, 'Redline vs Vulcan');
});

test('getRarity matches the tier each skin is listed in', () => {
    allSkins.forEach(s => assert.equal(data.getRarity(s), s.rarity, s.name));
    assert.equal(data.getRarity({ id: 999999 }), 'consumer');
});

test('original cases keep id, name, price and theme key', () => {
    Object.keys(ORIGINAL_CASES).forEach(id => {
        const c = data.cases.find(x => x.id === Number(id));
        assert.ok(c, 'case ' + id);
        assert.deepEqual([c.name, c.price, c.theme.key], ORIGINAL_CASES[id]);
    });
    assert.equal(data.cases.find(c => c.price === 0.5).id, 1, 'cases[0] stays the cheapest (Caja Principiante)');
    assert.equal(data.cases[0].id, 1);
});

test('cases: unique ids / names / theme keys, categories match prices', () => {
    assert.equal(new Set(data.cases.map(c => c.id)).size, data.cases.length);
    assert.equal(new Set(data.cases.map(c => c.name)).size, data.cases.length);
    assert.equal(new Set(data.cases.map(c => c.theme.key)).size, data.cases.length);
    data.cases.forEach(c => {
        assert.ok(['cheap', 'medium', 'expensive'].includes(c.category), c.name);
        assert.equal(c.category, c.price <= 3.5 ? 'cheap' : c.price <= 15 ? 'medium' : 'expensive', c.name);
        assert.match(c.theme.primary, /^#[0-9a-f]{6}$/i);
        assert.match(c.theme.dark, /^#[0-9a-f]{6}$/i);
    });
    ['cheap', 'medium', 'expensive'].forEach(cat => assert.ok(data.cases.filter(c => c.category === cat).length >= 3, cat));
});

test('every case theme has artwork in case-art.js', () => {
    const src = fs.readFileSync(path.join(__dirname, '..', 'public', 'js', 'case-art.js'), 'utf8');
    data.cases.forEach(c => assert.ok(new RegExp('T\\.' + c.theme.key + '\\s*=\\s*function').test(src), 'no art for theme ' + c.theme.key));
    // each theme function stays small (< 6 KB of source)
    const parts = src.split(/\n    T\.(?=\w+ = function)/).slice(1);
    parts.forEach(p => assert.ok(p.length < 6000, 'theme ' + p.slice(0, 12) + ' is ' + p.length + ' bytes'));
});

test('case contents: real skins, explicit odds adding up to 100, rarest item still reachable', () => {
    data.cases.forEach(c => {
        assert.ok(c.items.length >= 8, c.name + ' has ' + c.items.length + ' items');
        const ids = new Set();
        c.items.forEach(it => {
            const s = allSkins.find(x => x.id === it.id);
            assert.ok(s, c.name + ': unknown skin ' + it.id);
            assert.equal(it.name, s.name);
            assert.equal(it.price, s.price);
            assert.equal(it.image, s.image);
            assert.ok(it.odds > 0, c.name + ': ' + it.name + ' has no odds');
            assert.ok(!ids.has(it.id), c.name + ': duplicate ' + it.name);
            ids.add(it.id);
        });
        const chances = data.getItemChances(c.items);
        assert.ok(Math.abs(chances.reduce((a, b) => a + b, 0) - 100) < 1e-6, c.name);
        assert.ok(Math.min.apply(null, chances) >= 0.0003, c.name + ' has an unreachable item');
    });
});

test('house edge: expected value of every case is 80-95% of its price (never above 100%)', () => {
    const rows = data.cases.map(c => {
        const ratio = evOf(c) / c.price;
        return { name: c.name, price: c.price, ev: evOf(c), ratio };
    });
    rows.forEach(r => {
        assert.ok(r.ratio >= 0.80 && r.ratio <= 0.95, r.name + ' EV/price = ' + (r.ratio * 100).toFixed(1) + '%');
    });
    if (process.env.CATALOG_REPORT) {
        rows.forEach(r => console.log(r.name.padEnd(20), r.price.toFixed(2).padStart(8), r.ev.toFixed(3).padStart(9), (r.ratio * 100).toFixed(1) + '%'));
    }
});

test('rollItem follows the odds: rng 0 picks the first item, rng ~1 the last; frequencies match', () => {
    const c = data.cases[0];
    assert.equal(data.rollItem(c.items, () => 0), c.items[0]);
    assert.equal(data.rollItem(c.items, () => 0.9999999), c.items[c.items.length - 1]);
    // deterministic sweep: the share of each item over a fine grid equals its odds
    const N = 20000, hits = new Map();
    for (let i = 0; i < N; i++) {
        const it = data.rollItem(c.items, () => (i + 0.5) / N);
        hits.set(it.id, (hits.get(it.id) || 0) + 1);
    }
    const chances = data.getItemChances(c.items);
    c.items.forEach((it, i) => {
        assert.ok(Math.abs((hits.get(it.id) || 0) / N * 100 - chances[i]) < 0.02, it.name);
    });
});

test('getItemChances falls back to the rarity model for lists without odds', () => {
    const items = [data.skins.consumer[0], data.skins.consumer[1], data.skins.gold[0]];
    const chances = data.getItemChances(items);
    assert.ok(Math.abs(chances.reduce((a, b) => a + b, 0) - 100) < 1e-9);
    assert.ok(Math.abs(chances[0] - chances[1]) < 1e-9);
    assert.ok(chances[0] > chances[2]);
});

test('formatChance handles tiny odds', () => {
    assert.equal(data.formatChance(50), '50.0%');
    assert.equal(data.formatChance(0.5), '0.50%');
    assert.equal(data.formatChance(0.0123), '0.012%');
    assert.equal(data.formatChance(0.0001), '<0.001%');
});
